package org.kanger;
import java.util.*;
import org.kanger.ContextUniversalFrozenConstraints.Result;
import org.kanger.ContextUniversalValidationSession.*;
import org.kanger.ContextProductionCapture.Support;

/** Exact immutable-frame/depth reuse, bounded lifetime and failure controls. */
public final class ContextUniversalValidationSessionRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    interface Action{void run()throws Exception;}
    static void reject(Action action,String why)throws Exception{boolean failed=false;try{action.run();}catch(IllegalStateException|IllegalArgumentException expected){failed=true;}require(failed,why);}
    static Result equal(Result r){Result copy=ContextUniversalFrozenConstraints.closeSignedCompounds(r.input,r.common,r.pool,r.exchange,r.compounds,16,16,512,256,WORK);require(copy.closed,copy.reason);require(copy!=r&&ContextUniversalGroupedLocalRounds.sameContents(copy,r,ContextGroundProductionRounds.budget(WORK)),"equal content is still a different actual Result");return copy;}
    static void contract()throws Exception {
        ContextUniversalGroupedChainAuditRunner.Fixture f=new ContextUniversalGroupedChainAuditRunner.Fixture(false,false);ContextUniversalGroupedLocalRounds.Certificate cert=f.trace.history.get(1).certificates.get(ContextWitnessResultTransport.Cut.of(f.b));Result r=cert.initial,copy=equal(r);
        long[] baseline={0};Runnable budget=ContextGroundProductionRounds.budget(WORK);ContextUniversalGroupedLocalRounds.check(cert,()->{++baseline[0];budget.run();});Metrics m=ContextUniversalValidationSession.checkCertificate(cert,WORK,4096);require(m.hits>0&&m.work<baseline[0]&&m.entries<=4096,"real repeated-authentication work reduced without increasing budget");System.out.println("SESSION_CERTIFICATE baseline="+baseline[0]+" reused="+m.work+" hits="+m.hits+" verified="+m.verified+" peak="+m.peakEntries);
        try(Scope s=ContextUniversalValidationSession.open(WORK,4096)){
            ContextUniversalFrozenConstraints.check(r,64,s.work);Metrics a=s.metrics();ContextUniversalFrozenConstraints.check(r,64,s.work);Metrics b=s.metrics();require(b.hits==a.hits+1&&b.work==a.work+1&&b.verified==a.verified,"same actual frame/depth lookup still costs one work tick");
            ContextUniversalFrozenConstraints.check(copy,64,s.work);Metrics c=s.metrics();require(c.verified>b.verified,"equal but distinct Result cannot reuse top-level authentication");
            ContextUniversalFrozenConstraints.check(r,16,s.work);Metrics d=s.metrics();require(d.verified>c.verified,"another maximum depth is a separate authentication policy");
            reject(()->ContextUniversalFrozenConstraints.check(r,0,s.work),"larger depth result cannot authorize strict depth0");require(s.metrics().entries==0,"any failed check clears prior successes");reject(()->ContextUniversalFrozenConstraints.check(r,64,s.work),"poisoned session cannot reuse an earlier success");
        }
        Scope closed=ContextUniversalValidationSession.open(WORK,4096);Runnable escaped=closed.work;ContextUniversalFrozenConstraints.check(r,64,escaped);require(closed.metrics().entries>0,"session contains only completed bounded entries");closed.close();require(closed.metrics().entries==0,"close releases every retained Result/frame");reject(escaped::run,"escaped callback cannot outlive lexical session");reject(()->ContextUniversalFrozenConstraints.check(r,64,escaped),"closed cache cannot authorize a fresh check");
        try(Scope fresh=ContextUniversalValidationSession.open(1,4096)){reject(()->ContextUniversalFrozenConstraints.check(r,64,fresh.work),"another invocation has no reusable old success");require(fresh.metrics().entries==0,"interrupted authentication leaves no completed prefix");}
        ContextWitnessResultTransport.Packet same=ContextPrivateWitnessPoolRunner.common(f.x);require(ContextWitnessResultTransport.sameContents(r.common,same,WORK),"equal content but different actual common frame control");java.lang.reflect.Field common=Result.class.getDeclaredField("common");common.setAccessible(true);Object actualCommon=common.get(r);try(Scope s=ContextUniversalValidationSession.open(WORK,4096)){ContextUniversalFrozenConstraints.check(r,64,s.work);common.set(r,same);try{reject(()->ContextUniversalFrozenConstraints.check(r,64,s.work),"changed actual common pointer cannot reuse cached old frame");}finally{common.set(r,actualCommon);}}
        Metrics small=ContextUniversalValidationSession.checkAll(Arrays.asList(new Request(r,64),new Request(copy,64),new Request(r,64)),WORK,1);require(small.peakEntries==1&&small.capacityBypass>0&&small.hits>=1,"capacity1 falls back to real checks without semantic acceptance shortcut");
        Metrics batch=ContextUniversalValidationSession.checkAll(Arrays.asList(new Request(r,64),new Request(r,64)),WORK,4096);require(batch.hits>=1,"bounded batch validates actual repeated frames");reject(()->ContextUniversalValidationSession.checkAll(Arrays.asList(new Request(r,64),new Request(null,64)),WORK,4096),"bad late request publishes no successful summary");reject(()->ContextUniversalValidationSession.open(WORK,0),"nonpositive cache bound");reject(()->ContextUniversalValidationSession.open(WORK,4097),"oversized cache bound");reject(()->ContextUniversalValidationSession.open(0,1),"nonpositive work bound");
        try(Scope s=ContextUniversalValidationSession.open(WORK,4096)){Throwable[] failure={null};Thread t=new Thread(()->{try{s.work.run();}catch(Throwable x){failure[0]=x;}});t.start();t.join();require(failure[0] instanceof IllegalStateException,"another thread cannot use session authority");ContextUniversalFrozenConstraints.check(r,64,s.work);}
        // A NEW invalid result must poison the whole session, including earlier valid graph entries.
        Result bad=equal(r);ContextUniversalFrozenConstraints.Proof root=bad.proofs.stream().filter(p->p.original!=null).findFirst().get();java.lang.reflect.Field support=root.getClass().getDeclaredField("support");support.setAccessible(true);Support original=root.support;support.set(root,new Support(Collections.singleton(f.a.primary.get(0).source),original.depth));
        try(Scope s=ContextUniversalValidationSession.open(WORK,4096)){ContextUniversalFrozenConstraints.check(r,64,s.work);reject(()->ContextUniversalFrozenConstraints.check(bad,64,s.work),"failed whole physical Source proof cannot be stored");require(s.metrics().entries==0,"Source forgery invalidates all session entries");reject(()->ContextUniversalFrozenConstraints.check(r,64,s.work),"no success after Source forgery even for previously good frame");}finally{support.set(root,original);}
        require(ContextUniversalValidationSession.checkAll(Collections.singletonList(new Request(bad,64)),WORK,4096).verified>0,"fresh repaired frame is fully checked in a fresh invocation");
    }
    static void privateCase()throws Exception {
        ContextUniversalGroupedChainAuditRunner.Fixture f=new ContextUniversalGroupedChainAuditRunner.Fixture(false,true);ContextUniversalGroupedLocalRounds.Certificate c=f.trace.history.get(0).certificates.get(ContextWitnessResultTransport.Cut.of(f.b));List<ContextUniversalFrozenConstraints.Proof> inventory=c.output.proofs;Metrics good=ContextUniversalValidationSession.checkCertificate(c,WORK,4096);require(good.hits>0&&c.output.proofs==inventory,"actual private Origin proof inventory remains unchanged");
        ContextUniversalFrozenConstraints.Proof p=c.output.proofs.stream().filter(q->q.grouped!=null).findFirst().get();Support old=p.support;java.lang.reflect.Field support=p.getClass().getDeclaredField("support");support.setAccessible(true);support.set(p,new Support(old.sources,old.depth+1));try{reject(()->ContextUniversalValidationSession.checkCertificate(c,WORK,4096),"fresh session must reject previously valid now forged grade");}finally{support.set(p,old);}
        java.lang.reflect.Field manifest=c.output.getClass().getDeclaredField("groupedInputs");manifest.setAccessible(true);Object full=manifest.get(c.output);manifest.set(c.output,Collections.emptyList());try{reject(()->ContextUniversalValidationSession.checkCertificate(c,WORK,4096),"fresh session cannot reuse success after complete manifest omission");}finally{manifest.set(c.output,full);}
        java.lang.reflect.Field base=c.output.getClass().getDeclaredField("groupedBase");base.setAccessible(true);Object before=base.get(c.output);base.set(c.output,c.output);try{reject(()->ContextUniversalValidationSession.checkAll(Collections.singletonList(new Request(c.output,64)),WORK,4096),"in-progress key is never mistaken for a completed check");}finally{base.set(c.output,before);}
    }
    static void originsAndRefutation()throws Exception {
        org.kanger.ContextProductionNativeBinding.Snapshot x=ContextUniversalGroupedRoundsRunner.bind(true,"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);"),a=ContextUniversalGroupedRoundsRunner.bind(false,"!$u $v a(u,1)&&a(v,1)&&hidden(u,1);"),b=ContextUniversalGroupedRoundsRunner.bind(false,"!@u b(u,2);");ContextWitnessResultTransport.Packet common=ContextPrivateWitnessPoolRunner.common(x);ContextWitnessResultTransport.PrivatePool pool=ContextWitnessResultTransport.privatePool(common,x,a,WORK);org.kanger.ContextUniversalCompoundExchange.Exchange e=ContextUniversalGroupedRoundsRunner.exchange(x,Arrays.asList(a,b),common,Collections.singletonMap(pool.cut,pool));Result base=ContextUniversalFrozenConstraints.closeSignedCompounds(ContextUniversalCompoundExchangeRunner.rows(x,b),common,null,null,e,16,16,512,256,WORK);require(base.closed,base.reason);ContextUniversalGroupedLocalRounds.Closure local=ContextUniversalGroupedLocalRounds.run(base,ContextUniversalGroupedRoundsRunner.local());require(local.stable,local.reason);ContextUniversalValidationSession.checkCertificate(local.output,WORK,4096);List<ContextUniversalFrozenConstraints.Proof> products=new ArrayList<>();for(ContextUniversalFrozenConstraints.Proof p:local.output.output.proofs)if(p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals("r"))products.add(p);require(products.size()==2&&products.get(0).support.equals(products.get(1).support)&&!products.get(0).clause.origins.equals(products.get(1).clause.origins),"same physical Source/grade does not merge distinct private binder Origins");
        org.kanger.ContextProductionNativeBinding.Snapshot bad=ContextUniversalGroupedRoundsRunner.bind(false,"!@u b(u,2); !@u ~r(u,2);");org.kanger.ContextUniversalCompoundExchange.Exchange conflicting=ContextUniversalGroupedRoundsRunner.exchange(x,Arrays.asList(a,bad),common,Collections.singletonMap(pool.cut,pool));Result refuted=ContextUniversalFrozenConstraints.closeSignedCompounds(ContextUniversalCompoundExchangeRunner.rows(x,bad),common,null,null,conflicting,16,16,512,256,WORK);require(refuted.closed&&refuted.xRefuted&&!refuted.emptyProofs.isEmpty(),"actual sourced refutation fixture");Metrics authenticated=ContextUniversalValidationSession.checkAll(Collections.singletonList(new Request(refuted,64)),WORK,4096);require(authenticated.verified>0&&refuted.xRefuted&&!refuted.emptyProofs.isEmpty(),"successful authentication of refutation grants no unrefuted/admission verdict");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("validation-session-").toString());contract();privateCase();originsAndRefutation();System.out.println("CONTEXT_UNIVERSAL_VALIDATION_SESSION_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
